27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
39	import org.springframework.samples.petclinic.rest.advice.OwnerDailyRegistrationLimitException;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.samples.petclinic.util.AddressNormalizer;
49	import org.springframework.samples.petclinic.util.BusinessDayAdjuster;
50	import org.springframework.samples.petclinic.util.EmailNormalizer;
51	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
52	import org.springframework.samples.petclinic.util.OwnerIdentity;
53	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
73	     * carrying the new owner's id, customer code and registration date.
74	     */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /**
78	     * Maximum number of owners a single city may hold. A create whose city already contains this many
79	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
80	     */
81	    private static final int MAX_OWNERS_PER_CITY = 50;
82	
83	    /**
84	     * Maximum number of owners that may be registered in a single day. A create made once this many
85	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
86	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
87	     */
88	    private static final int MAX_OWNERS_PER_DAY = 100;
89	
90	    /**
91	     * The number of owners that must already carry a given day's {@code registrationDate} before a
92	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
93	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
94	     */
95	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        normalizeAddress(ownerFieldsDto);
144	        rejectBlankOwnerFields(ownerFieldsDto);
145	        normalizeTelephone(ownerFieldsDto);
146	        normalizeEmail(ownerFieldsDto);
147	        String householdId = HouseholdNormalizer.toHouseholdId(
148	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
149	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
150	        rejectCityAtCapacity(ownerFieldsDto.getCity());
151	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
152	        long registeredThatDay = countRegisteredOn(registrationDate);
153	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        owner.setRegistrationDate(registrationDate);
157	        owner.setHouseholdId(householdId);
158	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
159	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
160	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
161	        this.clinicService.saveOwner(owner);
162	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
163	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
164	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        currentOwner.setAddress(ownerFieldsDto.getAddress());
178	        currentOwner.setCity(ownerFieldsDto.getCity());
179	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
180	        currentOwner.setLastName(ownerFieldsDto.getLastName());
181	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
182	        normalizeEmail(ownerFieldsDto);
183	        currentOwner.setEmail(ownerFieldsDto.getEmail());
184	        currentOwner.setHouseholdId(
185	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
186	        this.clinicService.saveOwner(currentOwner);
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Transactional
192	    @Override
193	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        this.clinicService.deleteOwner(owner);
199	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        HttpHeaders headers = new HttpHeaders();
210	        Pet pet = petMapper.toPet(petFieldsDto);
211	        owner.setId(ownerId);
212	        pet.setOwner(owner);
213	        pet.getType().setName(null);
214	        this.clinicService.savePet(pet);
215	        PetDto petDto = petMapper.toPetDto(pet);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
217	            .buildAndExpand(pet.getId()).toUri());
218	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner != null) {
226	            Pet currentPet = this.clinicService.findPetById(petId);
227	            if (currentPet != null) {
228	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
229	                currentPet.setName(petFieldsDto.getName());
230	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
231	                this.clinicService.savePet(currentPet);
232	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
241	        HttpHeaders headers = new HttpHeaders();
242	        Visit visit = visitMapper.toVisit(visitFieldsDto);
243	        Pet pet = new Pet();
244	        pet.setId(petId);
245	        visit.setPet(pet);
246	        this.clinicService.saveVisit(visit);
247	        VisitDto visitDto = visitMapper.toVisitDto(visit);
248	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
249	            .buildAndExpand(visit.getId()).toUri());
250	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
251	    }
252	
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner != null) {
259	            Pet pet = owner.getPet(petId);
260	            if (pet != null) {
261	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
262	            }
263	        }
264	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	    }
266	
267	    /**
268	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
269	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
270	     * the request body already rejects null and empty values, but permits whitespace-only strings
271	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
272	     * that gap so every required field must carry a non-blank value.
273	     *
274	     * @param ownerFieldsDto the submitted owner fields
275	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
276	     */
277	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
278	        List<String> missing = new ArrayList<>();
279	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
280	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
281	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
282	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
283	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
284	        if (!missing.isEmpty()) {
285	            throw new InvalidOwnerFieldsException(missing);
286	        }
287	    }
288	
289	    private void addIfBlank(List<String> missing, String fieldName, String value) {
290	        if (value == null || value.isBlank()) {
291	            missing.add(fieldName);
292	        }
293	    }
294	
295	    /**
296	     * Normalizes the submitted {@code address} on create to its canonical form (see
297	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
298	     * stored and returned, and the form every later address comparison (the required-field check,
299	     * household duplicate detection and the shared household id) is judged on. A null address is left
300	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
301	     * after normalization likewise reduces to the empty string and is rejected there.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields
304	     */
305	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
306	        String address = ownerFieldsDto.getAddress();
307	        if (address == null) {
308	            return;
309	        }
310	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
311	    }
312	
313	    /**
314	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
315	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
316	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
317	     * {@code 400 Bad Request}.
318	     *
319	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
320	     *                       {@link #rejectBlankOwnerFields} having already run)
321	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
322	     */
323	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
324	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
325	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
326	        ownerFieldsDto.setTelephone(normalized);
327	    }
328	
329	    /**
330	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
331	     * untouched (email is optional). When present it is reduced to its canonical form (see
332	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
333	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
334	     *
335	     * @param ownerFieldsDto the submitted owner fields
336	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
337	     */
338	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
339	        String email = ownerFieldsDto.getEmail();
340	        if (email == null || email.isBlank()) {
341	            return;
342	        }
343	        String normalized = EmailNormalizer.normalize(email)
344	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
345	        ownerFieldsDto.setEmail(normalized);
346	    }
347	
348	    /**
349	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
350	     * duplicate detection is now expressed through the single derived {@code identityKey}
351	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
352	     * which replaces the previously separate telephone, email and household checks. Two owners denote
353	     * the same person when their identities collide on the telephone - the identity's distinguishing
354	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
355	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
356	     * same household with different telephones have different identities and are both allowed; an email
357	     * or a household on its own no longer makes a duplicate.
358	     *
359	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
360	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
361	     * @param householdId    the household id derived for the owner being created (see
362	     *                       {@link HouseholdNormalizer#toHouseholdId})
363	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
364	     */
365	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
366	        String identityKey = OwnerIdentity.identityKey(
367	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
368	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
369	        boolean inUse = this.clinicService.findAllOwners().stream()
370	            .map(Owner::getTelephone)
371	            .filter(Objects::nonNull)
372	            .map(TelephoneNormalizer::toComparisonKey)
373	            .anyMatch(telephoneKey::equals);
374	        if (inUse) {
375	            throw new DuplicateOwnerIdentityException(identityKey);
376	        }
377	    }
378	
379	    /**
380	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
381	     * both match the submitted values, compared case-insensitively. The count reflects only owners
382	     * already persisted at the time of the create, so the owner being created is never included.
383	     *
384	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
385	     *                  having already run)
386	     * @param lastName  the submitted last name (non-blank here)
387	     * @return the number of existing owners sharing the same first and last name
388	     */
389	    private int countNamesakes(String firstName, String lastName) {
390	        return (int) this.clinicService.findAllOwners().stream()
391	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
392	                && lastName.equalsIgnoreCase(owner.getLastName()))
393	            .count();
394	    }
395	
396	    /**
397	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
398	     * whose stored {@code householdId} equals the value derived for the owner being created. The
399	     * count reflects only owners already persisted at the time of the create, so the owner being
400	     * created is never included; callers add one to obtain the household size after this create.
401	     *
402	     * @param householdId the household identifier derived for the owner being created (see
403	     *                    {@link HouseholdNormalizer#toHouseholdId})
404	     * @return the number of existing owners already sharing that household
405	     */
406	    private int countHouseholdMembers(String householdId) {
407	        if (householdId == null) {
408	            return 0;
409	        }
410	        return (int) this.clinicService.findAllOwners().stream()
411	            .map(Owner::getHouseholdId)
412	            .filter(householdId::equals)
413	            .count();
414	    }
415	
416	    /**
417	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
418	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
419	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
420	     *
421	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
422	     *             run)
423	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
424	     */
425	    private void rejectCityAtCapacity(String city) {
426	        long ownersInCity = this.clinicService.findAllOwners().stream()
427	            .map(Owner::getCity)
428	            .filter(Objects::nonNull)
429	            .filter(city::equalsIgnoreCase)
430	            .count();
431	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
432	            throw new OwnerCityAtCapacityException(city);
433	        }
434	    }
435	
436	    /**
437	     * Resolves the effective registration date for a create, rolled onto a business day. The
438	     * supplied date is used when present, otherwise the server's current date; either way the result
439	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
440	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
441	     * stored {@code registrationDate}, the membership number's year segment and the daily
442	     * create-limit's per-day count - is judged on this adjusted date.
443	     *
444	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
445	     *                                 default to the server's current date
446	     * @return the effective registration date, guaranteed to fall on a business day
447	     */
448	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
449	        LocalDate registrationDate =
450	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
451	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
452	    }
453	
454	    /**
455	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
456	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
457	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
458	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
459	     * Too Many Requests}.
460	     *
461	     * @param registrationDate   the create's effective registration date, already rolled onto a
462	     *                           business day by {@link #effectiveRegistrationDate}
463	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
464	     *                           {@code registrationDate} equals {@code registrationDate}
465	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
466	     *                                              owner registrations
467	     */
468	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
469	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
470	            throw new OwnerDailyRegistrationLimitException(registrationDate);
471	        }
472	    }
473	
474	    /**
475	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
476	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
477	     * bulk-signup warning are judged on.
478	     *
479	     * @param registrationDate the create's effective registration date, already rolled onto a business
480	     *                         day by {@link #effectiveRegistrationDate}
481	     * @return the number of existing owners registered on that day
482	     */
483	    private long countRegisteredOn(LocalDate registrationDate) {
484	        return this.clinicService.findAllOwners().stream()
485	            .map(Owner::getRegistrationDate)
486	            .filter(registrationDate::equals)
487	            .count();
488	    }
489	}
